import Foundation
import Vision
import ImageIO

let root = URL(fileURLWithPath: CommandLine.arguments[1], isDirectory: true)
let output = URL(fileURLWithPath: CommandLine.arguments[2], isDirectory: true)
try FileManager.default.createDirectory(at: output, withIntermediateDirectories: true)
let files = try FileManager.default.contentsOfDirectory(at: root, includingPropertiesForKeys: nil)
    .filter { ["heic", "png"].contains($0.pathExtension.lowercased()) }
    .sorted { $0.lastPathComponent < $1.lastPathComponent }
precondition(files.count == 19, "图片数量变化，需要重新核对输入")
for file in files {
    let request = VNRecognizeTextRequest()
    request.recognitionLevel = .accurate
    request.recognitionLanguages = ["zh-Hans", "en-US"]
    request.usesLanguageCorrection = true
    let source = CGImageSourceCreateWithURL(file as CFURL, nil)!
    let properties = CGImageSourceCopyPropertiesAtIndex(source, 0, nil) as? [CFString: Any]
    let orientation = CGImagePropertyOrientation(rawValue: properties?[kCGImagePropertyOrientation] as? UInt32 ?? 1)!
    let handler = VNImageRequestHandler(url: file, orientation: orientation)
    try handler.perform([request])
    let observations = request.results ?? []
    precondition(!observations.isEmpty, "图片未识别出文字：\(file.lastPathComponent)")
    let lines = observations.compactMap { $0.topCandidates(1).first?.string }
    try lines.joined(separator: "\n").write(to: output.appendingPathComponent(file.lastPathComponent + ".txt"), atomically: true, encoding: .utf8)
    print("\(file.lastPathComponent): \(lines.count)行")
}
